import React,{useEffect,useState} from 'react';
import {Star,Plus,Upload,Users,Grid2X2,Download,Trash2,Tag,Save} from 'lucide-react';
import type {HostAdapter} from '../host/adapter';
import type {Data,Item} from '../host/types';
import {clone} from '../host/model';
import {useHost,useTask,SearchBox,Notice,Empty,Field,IconButton,NativeLink,Row} from '../ui/common';
export default function Characters({host,management,onManage}:{host:HostAdapter,management?:boolean,onManage?:()=>void}){
 const snap=useHost(host),task=useTask(),[query,setQuery]=useState(''),[tab,setTab]=useState('all'),[favOnly,setFavOnly]=useState(false),[tag,setTag]=useState(''),[sort,setSort]=useState('name'),[selected,setSelected]=useState<string[]>([]),[editing,setEditing]=useState<string|null>(null);
 const favorite=(x:Item)=>Boolean(x.data?.data?.extensions?.fav??x.data?.fav),favorites=snap.characters.filter(favorite);
 const tags=[...new Set(snap.characters.flatMap(x=>x.data?.data?.tags??[]))] as string[];
 const list=snap.characters.filter(x=>(!favOnly||favorite(x))&&(!tag||x.data?.data?.tags?.includes(tag))&&`${x.name} ${x.detail}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='recent'?Number(b.data?.date_last_chat??0)-Number(a.data?.date_last_chat??0):a.name.localeCompare(b.name,'zh'));
 const open=(item:Item)=>{if(management){setEditing(item.id);}else{task.run(async()=>{await host.selectCharacter(item.id);setTab('current');});}};
 return <div className={`wb-characters ${management?'is-management':''}`}><Notice error={task.error}/>
  {!management&&<><div className="wb-section-title"><span>收藏角色</span><span className="wb-grow"/>{onManage&&<button className="wb-link" onClick={onManage}>管理<Grid2X2 size={14}/></button>}</div><div className="wb-favorites">{favorites.map(x=><button key={x.id} title={x.name} onClick={()=>open(x)} className={x.active?'is-active':''}><img src={x.image}/><span>{x.name}</span></button>)}{!favorites.length&&<small>收藏常用角色，便于快速切换</small>}</div><div className="wb-tabs"><button className={tab==='all'?'is-active':''} onClick={()=>setTab('all')}>全部角色</button><button className={tab==='current'?'is-active':''} onClick={()=>setTab('current')}>当前角色</button><span className="wb-grow"/><small>{snap.characters.length} 位</small></div></>}
  {management&&<aside className="wb-library-filters"><span className="wb-eyebrow">角色库</span><h2>故事里的人</h2><button className={!favOnly?'is-active':''} onClick={()=>setFavOnly(false)}>全部角色 <span>{snap.characters.length}</span></button><button className={favOnly?'is-active':''} onClick={()=>setFavOnly(true)}><Star size={16}/>我的收藏 <span>{favorites.length}</span></button><p className="wb-caption">标签</p><button className={!tag?'is-active':''} onClick={()=>setTag('')}>所有标签</button>{tags.map(t=><button key={t} className={tag===t?'is-active':''} onClick={()=>setTag(t)}>{t}</button>)}<NativeLink onClick={()=>host.native('character')}>导入 / 新建 / 群组</NativeLink></aside>}
  {(tab==='all'||management)&&!editing?<section className="wb-library-content"><div className="wb-list-tools"><SearchBox value={query} onChange={setQuery} placeholder="搜索角色或标签"/><select aria-label="角色排序" value={sort} onChange={e=>setSort(e.target.value)}><option value="name">名称排序</option><option value="recent">最近对话</option></select></div><div className={management?'wb-card-grid':'wb-character-list'}>{list.map(x=><article key={x.id} className={`wb-character-card ${x.active?'is-active':''}`}>
   {management&&<input type="checkbox" aria-label={`选择 ${x.name}`} checked={selected.includes(x.id)} onChange={e=>setSelected(v=>e.target.checked?[...v,x.id]:v.filter(id=>id!==x.id))}/>}
   <button className="wb-character-main" onClick={()=>open(x)}><img src={x.image} alt=""/><span><strong>{x.name}</strong><small>{x.detail||'未分类角色'}</small>{x.active&&<em>当前角色</em>}</span></button><IconButton title={favorite(x)?`取消收藏 ${x.name}`:`收藏 ${x.name}`} onClick={()=>task.run(()=>host.favorite(x))}><Star size={16} fill={favorite(x)?'currentColor':'none'}/></IconButton>
   {management&&<button className="wb-link" onClick={()=>task.run(()=>host.selectCharacter(x.id))}>开始对话 →</button>}</article>)}</div>{!list.length&&<Empty>没有符合条件的角色</Empty>}
   {management&&<footer className="wb-batch"><label><input type="checkbox" checked={list.length>0&&list.every(x=>selected.includes(x.id))} onChange={e=>setSelected(e.target.checked?list.map(x=>x.id):[])}/>选择当前结果</label><span>{selected.length} 项</span><span className="wb-grow"/><button disabled={!selected.length||task.busy} onClick={()=>{const value=prompt('添加标签');if(value)task.run(()=>host.tagCharacters(selected,value));}}><Tag size={15}/>标签</button><button disabled={!selected.length||task.busy} onClick={()=>task.run(async()=>{for(const id of selected)await host.exportCharacter(id);})}><Download size={15}/>导出</button><button disabled={!selected.length||task.busy} onClick={()=>{if(confirm(`删除选中的 ${selected.length} 个角色卡？聊天文件保留。此操作无法在工作台撤销，建议先导出。`))task.run(async()=>{await host.deleteCharacters(selected);setSelected([]);});}}><Trash2 size={15}/>删除</button></footer>}
  </section>:<div className="wb-character-detail-wrap">{editing&&<button className="wb-link" onClick={()=>{const e=new Event('wb-before-close',{cancelable:true});if(window.dispatchEvent(e))setEditing(null);}}>← 返回角色库</button>}{(editing||snap.character)?<CharacterEditor key={editing||snap.character!.id} id={editing||snap.character!.id} host={host}/>:<Empty>先选择角色</Empty>}</div>}
  {!management&&<footer className="wb-resource-footer"><button onClick={()=>{host.native('character');host.click('#rm_button_create');}}><Plus size={16}/>新建</button><button onClick={()=>host.native('character')}><Upload size={16}/>导入</button><button onClick={()=>{host.native('character');host.click('#rm_button_group_chats');}}><Users size={16}/>群组</button>{onManage&&<button onClick={onManage}><Grid2X2 size={16}/>独立管理</button>}</footer>}
 </div>;
}
function CharacterEditor({host,id}:{host:HostAdapter,id:string}){
 const task=useTask(),[base,setBase]=useState<Data|null>(null),[draft,setDraft]=useState<Data|null>(null),[message,setMessage]=useState('');
 const dirty=!!base&&JSON.stringify(base)!==JSON.stringify(draft);
 useEffect(()=>{let live=true;host.characterData(id).then(c=>{if(live){setBase(clone(c.data??{}));setDraft(clone(c.data??{}));}}).catch(e=>task.setError(e.message));return()=>{live=false;};},[id]);
 useEffect(()=>{const guard=(e:Event)=>{if(dirty&&!confirm('角色有未保存修改，放弃这些修改？'))e.preventDefault();};const unload=(e:BeforeUnloadEvent)=>{if(dirty){e.preventDefault();e.returnValue='';}};window.addEventListener('wb-before-close',guard);window.addEventListener('beforeunload',unload);return()=>{window.removeEventListener('wb-before-close',guard);window.removeEventListener('beforeunload',unload);};},[dirty]);
 if(!draft||!base)return <Empty>正在读取角色…</Empty>;
 const field=(key:string,label:string,rows=4)=><Field label={label}><textarea rows={rows} value={draft[key]??''} onChange={e=>{setDraft({...draft,[key]:e.target.value});setMessage('');}}/></Field>;
 return <div className="wb-character-editor"><Notice error={task.error}/><div className="wb-role-heading"><img src={host.snapshot().characters.find(c=>c.id===id)?.image}/><Field label="角色名称"><input value={draft.name??''} onChange={e=>setDraft({...draft,name:e.target.value})}/></Field></div><Field label="标签（逗号分隔）"><input value={(draft.tags??[]).join(', ')} onChange={e=>setDraft({...draft,tags:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)})}/></Field>{field('description','角色描述',7)}{field('first_mes','第一条消息',6)}<details><summary>高级定义</summary>{field('personality','性格')}{field('scenario','场景')}{field('mes_example','对话示例')}{field('system_prompt','系统提示词')}{field('post_history_instructions','历史后指令')}</details><div className="wb-editor-footer"><small>{dirty?'未保存修改':message}</small><span className="wb-grow"/><button disabled={!dirty||task.busy} className="wb-primary" onClick={()=>task.run(async()=>{const data=await host.saveCharacter(id,base,draft);setBase(clone(data.data));setDraft(clone(data.data));setMessage('已保存');})}><Save size={15}/>保存</button></div><NativeLink onClick={()=>host.native('character')}>原生角色编辑与更多字段</NativeLink></div>;
}
